cd /home/computa/Projects/WIMS-BFP/WIMS-BFP-PROTOTYPE && python - <<'PY'
from pathlib import Path
root=Path('src/nginx/bot-blocker')
missing=[]
for p in sorted(root.rglob('*.conf')):
    for n,line in enumerate(p.read_text(errors='replace').splitlines(),1):
        s=line.strip()
        if not s.startswith('include '):
            continue
        target=s.split()[1].rstrip(';')
        if target.startswith('/etc/nginx/bot-blocker/'):
            rel=target.removeprefix('/etc/nginx/bot-blocker/')
            exists=(root/rel).exists()
        elif target.startswith('/etc/nginx/bots.d/'):
            rel='bots.d/'+target.removeprefix('/etc/nginx/bots.d/')
            exists=(root/rel).exists()
        else:
            exists=None
        missing.append((str(p),n,target,exists))
for row in missing:
    print(*row, sep=':')
PY

